// Makes a P-256 key pair from RFC 6979's key (section A.2.5) on the default backend, checks its
// public key against the RFC's, and prints the backend that ran. The scalar is the RFC's: a real
// program draws its own with keypair::generate().
#include <webcpp/crypto/curves/p256.hpp>

#include <array>
#include <cstdint>
#include <cstdio>

int main() {
    namespace p256 = webcpp::crypto::curves::p256;
    std::array<std::uint8_t, 32> const scalar{
        0xc9, 0xaf, 0xa9, 0xd8, 0x45, 0xba, 0x75, 0x16, 0x6b, 0x5c, 0x21,
        0x57, 0x67, 0xb1, 0xd6, 0x93, 0x4e, 0x50, 0xc3, 0xdb, 0x36, 0xe8,
        0x9b, 0x12, 0x7b, 0x8a, 0x62, 0x2b, 0x12, 0x0f, 0x67, 0x21,
    };
    std::array<std::uint8_t, 65> const expected{
        0x04, 0x60, 0xfe, 0xd4, 0xba, 0x25, 0x5a, 0x9d, 0x31, 0xc9, 0x61, 0xeb, 0x74,
        0xc6, 0x35, 0x6d, 0x68, 0xc0, 0x49, 0xb8, 0x92, 0x3b, 0x61, 0xfa, 0x6c, 0xe6,
        0x69, 0x62, 0x2e, 0x60, 0xf2, 0x9f, 0xb6, 0x79, 0x03, 0xfe, 0x10, 0x08, 0xb8,
        0xbc, 0x99, 0xa4, 0x1a, 0xe9, 0xe9, 0x56, 0x28, 0xbc, 0x64, 0xf2, 0xf1, 0xb2,
        0x0c, 0x2d, 0x7e, 0x9f, 0x51, 0x77, 0xa3, 0xc2, 0x94, 0xd4, 0x46, 0x22, 0x99,
    };
    auto const key = p256::keypair::from_secret(scalar);
    bool ok = false;
    if (key) {
        auto const public_key = key->public_key();
        ok = public_key && public_key->uncompressed() == expected;
    }
    auto const name = p256::keypair::backend_type::name;
    std::printf("p256 %s backend=%.*s\n", ok ? "ok" : "FAILED", static_cast<int>(name.size()),
                name.data());
    return ok ? 0 : 1;
}
